/// <summary>
/// CB705_Rebate batch jobs & Vendor payback extension
/// </summary>
/// <param name="sender">sender</param>
/// <param name="e">e</param>
[FormDataSourceEventHandler(formDataSourceStr(TAMRebateDeal, TAMRebateDate), FormDataSourceEventType::Activated)]
public static void TAMRebateDate_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormDataSource TAMRebateDeal_DS = sender.formRun().dataSource(formDataSourceStr(TAMRebateDeal, TAMRebateDeal));
    FormDataSource TAMRebateTable_DS = sender.formRun().dataSource(formDataSourceStr(TAMRebateDeal, TAMRebateTable));
    TAMRebateDeal TAMRebateDeal = TAMRebateDeal_DS.cursor();
    boolean allowEdit = TAMRebateDeal.State == TAMRebateDealWorkflowState::Draft
                            || TAMRebateDeal.State == TAMRebateDealWorkflowState::Cancelled
                            || TAMRebateDeal.State == TAMRebateDealWorkflowState::ChangeRequested;

    METTAMRebateTableEventHandler::allowEditASetOfFields(TAMRebateTable_DS, allowEdit);
    METTAMRebateTableEventHandler::controlVendPayBackFieldVisibility(TAMRebateTable_DS);
}

/// <summary>
/// CB705_Rebate batch jobs & Vendor payback extension. Control vendor pay back field visibility
/// </summary>
/// <param name = "_formDataSource">_formDataSource</param>
public static void controlVendPayBackFieldVisibility(FormDataSource _formDataSource)
{
    TAMRebateTable tamRebateTable = _formDataSource.cursor();
    if ((tamRebateTable.ModuleInventCustVend == ModuleInventCustVend::Cust) || (tamRebateTable.ModuleInventCustVend == ModuleInventCustVend::Invent))
    {
        _formDataSource.object(fieldNum(TAMRebateTable, METEnableVendorPayBack)).visible(false);
    }
    if (tamRebateTable.ModuleInventCustVend == ModuleInventCustVend::Vend)
    {
        _formDataSource.object(fieldNum(TAMRebateTable, METEnableVendorPayBack)).visible(true);
    }
}

/// <summary>
/// CB705_Rebate batch jobs & Vendor payback extension. Control allow edit for manual rebate posting and vendor pay back field
/// </summary>
/// <param name = "_formDataSource">Data source where fields will be editable</param>
/// <param name = "_allowEdit">Set perticular field allow edit property</param>
public static void allowEditASetOfFields(FormDataSource _formDataSource, boolean _allowEdit)
{
    if (!_allowEdit)
    {
        DictTable   dictTable = new DictTable(_formDataSource.table());

        _formDataSource.allowEdit(true);

        for(int i = 1; i <= dictTable.fieldCnt(); i++)
        {
            var fieldId = dictTable.fieldCnt2Id(i);
            FormDataObject  formDataObject = _formDataSource.object(fieldId);
            if (formDataObject)
            {

                if ((fieldNum(TAMRebateTable, METEnableVendorPayBack) == fieldId) ||
            (fieldNum(TAMRebateTable, METSkipPosting) == fieldId))
                {
                    formDataObject.allowEdit(true);
                }
                else
                {
                    formDataObject.allowEdit(_allowEdit);
                }

            }
        }
    }
}
